  /** 允许 loop-app 直接访问子模块（Engine.Renderer / Engine.Input / Engine.Math ...）。 */
  Engine.getModule = function (name) {
    return Engine[name] || null;
  };

  WX.Engine = Engine;
})(typeof window !== 'undefined' ? window : this);

